def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_int() -> int:
        nonlocal pos
        start = pos
        while pos < n and '0' <= expr[pos] <= '9':
            pos += 1
        if pos - start <= 4000:
            return int(expr[start:pos])
        val = 0
        i = start
        while i < pos:
            end = min(i + 1000, pos)
            val = val * (10 ** (end - i)) + int(expr[i:end])
            i = end
        return val

    def parse_primary() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == '(':
            pos += 1
            val = parse_add_sub()
            skip_spaces()
            pos += 1
            return val
        return parse_int()

    def parse_unary() -> int:
        nonlocal pos
        terms: list[tuple[bool, int]] = []
        while True:
            skip_spaces()
            neg = False
            while pos < n and expr[pos] == '-':
                neg = not neg
                pos += 1
                skip_spaces()
            base = parse_primary()
            terms.append((neg, base))
            skip_spaces()
            if pos < n and expr[pos] == '^':
                pos += 1
            else:
                break

        val = -terms[-1][1] if terms[-1][0] else terms[-1][1]
        for i in range(len(terms) - 2, -1, -1):
            if val < 0:
                raise ArithmeticError
            neg, base = terms[i]
            val = base ** val
            if neg:
                val = -val
        return val

    def parse_mul_div() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_spaces()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ('*', '/', '%'):
                break
            pos += 1
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            elif rhs == 0:
                raise ArithmeticError
            elif op == '/':
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) != (rhs < 0) else q
            else:
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
        return val

    def parse_add_sub() -> int:
        nonlocal pos
        val = parse_mul_div()
        while True:
            skip_spaces()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ('+', '-'):
                break
            pos += 1
            rhs = parse_mul_div()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    try:
        return parse_add_sub()
    except ArithmeticError:
        return "error"
